 catch(e){state=JSON.parse(backup);poems=[...LIBRARY,...state.custom];render(false);native('testDone',{text:JSON.stringify({checks,success:false,error:e.message})})}})();void 0;
 """,completionHandler:{_,error in if let error=error{print(error);NSApp.terminate(nil)}})}
