 func updateDesktop(){
 guard !isValidationRun,desktopEnabled,let image=lastImage else{return};let screens=NSScreen.screens;guard !screens.isEmpty else{return};let screen=screens[min(screenIndex,screens.count-1)]
 if desktopWindow == nil {let w=NSWindow(contentRect:screen.frame,styleMask:.borderless,backing:.buffered,defer:false);w.isReleasedWhenClosed=false;w.level=NSWindow.Level(rawValue:Int(CGWindowLevelForKey(.desktopWindow))+1);w.collectionBehavior=[.canJoinAllSpaces,.stationary,.ignoresCycle];w.ignoresMouseEvents=true;w.hasShadow=false;desktopWindow=w}
 let w=desktopWindow!;w.setFrame(screen.frame,display:true);let view=NSView(frame:NSRect(origin:.zero,size:screen.frame.size));view.wantsLayer=true;let bg=CALayer();bg.frame=view.bounds;bg.contents=image.cgImage(forProposedRect:nil,context:nil,hints:nil);bg.contentsGravity = .resizeAspectFill;bg.masksToBounds=true;view.layer?.addSublayer(bg)
 let text=CATextLayer();text.string=poemText;text.font=CTFontCreateWithName("Songti SC" as CFString,26,nil);text.fontSize=desktopFont;text.alignmentMode=desktopAlign == "center" ? .center : .left;text.foregroundColor=self.desktopColor.cgColor;text.shadowColor=NSColor.black.cgColor;text.shadowOpacity=desktopShadow;text.shadowRadius=6;text.contentsScale=screen.backingScaleFactor;text.isWrapped=true;text.frame=CGRect(x:view.bounds.width*0.57,y:view.bounds.height*0.13,width:view.bounds.width*0.37,height:view.bounds.height*0.7);bg.addSublayer(text);w.contentView=view;w.orderFrontRegardless()
