 @objc func toggleLogin(){do{if SMAppService.mainApp.status == .enabled{try SMAppService.mainApp.unregister()}else{try SMAppService.mainApp.register()};syncMenuChecks();if SMAppService.mainApp.status == .requiresApproval{SMAppService.openSystemSettingsLoginItems()}}catch{let a=NSAlert();a.messageText="登录项设置未完成";a.informativeText="系统返回：\(error.localizedDescription)\n如应用位于外置硬盘，登录时请确保硬盘已挂载。也可在系统设置→通用→登录项中手动添加诗栖。";NSApp.activate(ignoringOtherApps:true);a.runModal()}}
 @objc func menuAction(_ item:NSMenuItem){guard let cmd=item.representedObject as? String else{return};if cmd=="update"{restOverlay.finish();updater.checkForUpdates();return};if cmd.hasPrefix("screen:"),let index=Int(cmd.dropFirst(7)){chooseScreen(index);return};if ["screensaver","video","stopVideo","screens","desktop","hideDesktop","rest"].contains(cmd){perform(cmd);return};if ["gallery","custom","analysis","search","collection","history","settings","display","more"].contains(cmd){showInlinePanel(cmd);return};runWeb("command('\(cmd)')")}
 func perform(_ cmd:String){
 if cmd=="desktop" {desktopEnabled=true;updateDesktop();videoWindows.forEach{$0.orderFrontRegardless()};window.orderOut(nil)}
 if cmd=="hideDesktop" {desktopEnabled=false;desktopWindow?.orderOut(nil);videoWindows.forEach{$0.orderOut(nil)}}
 if cmd=="screensaver" {closeInlinePanel();window.orderOut(nil);runWeb("restStarted()");restOverlay.startScreensaver(image:lastImage,poem:poemText)}
 if cmd=="rest" {closeInlinePanel();window.orderOut(nil);runWeb("restStarted()");restOverlay.start(seconds:restDuration,image:lastImage,poem:poemText)}
 if cmd=="screens" {closeInlinePanel();let menu=screensMenu().submenu!;menu.popUp(positioning:nil,at:NSEvent.mouseLocation,in:nil)}
 if cmd=="stopVideo" {for p in players{p.pause()};for w in videoWindows{w.orderOut(nil)};for o in loopObservers{NotificationCenter.default.removeObserver(o)};videoWindows=[];players=[];loopObservers=[];videoTexts=[];reply("动态壁纸已停止")}
 if cmd=="video" {restOverlay.finish();closeInlinePanel();let panel=NSOpenPanel();panel.allowedContentTypes=[.movie];panel.canChooseDirectories=false;NSApp.activate(ignoringOtherApps:true);panel.begin{r in guard r == .OK, let url=panel.url else{return};self.perform("stopVideo");self.desktopEnabled=true;self.updateDesktop();let screens=NSScreen.screens;guard !screens.isEmpty else{return};let screen=screens[min(self.screenIndex,screens.count-1)];let w=NSWindow(contentRect:screen.frame,styleMask:.borderless,backing:.buffered,defer:false);w.isReleasedWhenClosed=false;w.level=NSWindow.Level(rawValue:Int(CGWindowLevelForKey(.desktopWindow))+2);w.collectionBehavior=[.canJoinAllSpaces,.stationary,.ignoresCycle];w.ignoresMouseEvents=true;let view=NSView(frame:NSRect(origin:.zero,size:screen.frame.size));view.wantsLayer=true;let player=AVPlayer(url:url);player.isMuted=true;let layer=AVPlayerLayer(player:player);layer.frame=view.bounds;layer.videoGravity = .resizeAspectFill;view.layer=layer;let text=CATextLayer();text.string=self.poemText;text.font=CTFontCreateWithName("Songti SC" as CFString,28,nil);text.fontSize=self.desktopFont;text.alignmentMode=self.desktopAlign == "center" ? .center : .left;text.foregroundColor=self.desktopColor.cgColor;text.shadowColor=NSColor.black.cgColor;text.shadowOpacity=self.desktopShadow;text.shadowRadius=5;text.contentsScale=screen.backingScaleFactor;text.isWrapped=true;text.frame=CGRect(x:screen.frame.width*0.6,y:screen.frame.height*0.18,width:screen.frame.width*0.35,height:screen.frame.height*0.65);layer.addSublayer(text);self.videoTexts.append(text);w.contentView=view;let o=NotificationCenter.default.addObserver(forName:.AVPlayerItemDidPlayToEndTime,object:player.currentItem,queue:.main){_ in player.seek(to:.zero);player.play()};self.loopObservers.append(o);self.players.append(player);self.videoWindows.append(w);w.orderFrontRegardless();player.play();self.reply("动态壁纸已开始，可在菜单中停止")}}
 }
